  }

  local font = ctx.readImage("fonts/font.png")
  local extra = ctx.readImage("fonts/font_extra.png")
  local fw, fh = font:getDimensions()
  local ew, eh = extra:getDimensions()

  for _, name in ipairs(tilesets) do
    local rel = "tilesets/" .. name .. ".png"
    if ctx.exists(rel) then
      local base = ctx.readImage(rel)
      local bw, bh = base:getDimensions()

      -- PrintNumber's two-digit item quantity field does not clamp values
      -- above 99.  Its tens value is added to the Gen-I digit base $f6, so
      -- 10..25 wrap to live BG tile ids $00..$0f.  Preserve those first
      -- sixteen tiles from every player-owned tileset as a tiny private font
      -- page.  The runtime selects the page belonging to the currently
      -- loaded map, reproducing the original map-dependent "glitch digit"
      -- without packaging any ROM-derived pixels.
      local quantityTiles = ctx.blank(16 * 8, 8, 1, 1, 1, 1)
      local tilesPerRow = math.floor(bw / 8)
      for tile = 0, 15 do
        ctx.blit(quantityTiles, base, tile * 8, 0,
          (tile % tilesPerRow) * 8, math.floor(tile / tilesPerRow) * 8,
          8, 8)
      end
      ctx.writeImage(quantityTiles,
        "fonts/g1gpp_item_quantity_" .. name .. ".png")

      -- Preserve the source atlas width/ordering, then append both font pages
      -- in four opaque contrast themes. Every glyph tile owns its background;
      -- no transparent character can expose noisy terrain beneath it.
      local themes = {
        { bg = 1.00, ink = 0.00 },
        { bg = 0.67, ink = 0.00 },
        { bg = 0.33, ink = 1.00 },
        { bg = 0.00, ink = 1.00 },
      }
      local outW = math.max(bw, fw, ew)
      local outH = bh + (fh + eh) * #themes
      local out = ctx.blank(outW, outH, 1, 1, 1, 1)

      ctx.blit(out, base, 0, 0)
      local pageY = bh
      for _, theme in ipairs(themes) do
        local fontSolid = ctx.blank(fw, fh, theme.bg, theme.bg, theme.bg, 1)
        local extraSolid = ctx.blank(ew, eh, theme.bg, theme.bg, theme.bg, 1)
        for y = 0, fh - 1 do
          for x = 0, fw - 1 do
            local _, _, _, a = font:getPixel(x, y)
            local alpha = a or 1
            local shade = theme.ink * alpha + theme.bg * (1 - alpha)
            fontSolid:setPixel(x, y, shade, shade, shade, 1)
          end
        end
        for y = 0, eh - 1 do
          for x = 0, ew - 1 do
            local _, _, _, a = extra:getPixel(x, y)
            local alpha = a or 1
            local shade = theme.ink * alpha + theme.bg * (1 - alpha)
            extraSolid:setPixel(x, y, shade, shade, shade, 1)
          end
        end
        ctx.blit(out, fontSolid, 0, pageY)
        ctx.blit(out, extraSolid, 0, pageY + fh)
        pageY = pageY + fh + eh
      end
      ctx.writeImage(out, "tilesets/g1gpp_" .. name .. ".png")
    end
  end

  -- Release-safe battle art. Private research captures are visual oracles
  -- only. Every image below is generated locally from deterministic geometry
  -- or from graphics in the player's own imported cache.
  local function setRect(image, x0, y0, w, h, shade)
    for y = y0, y0 + h - 1 do
      for x = x0, x0 + w - 1 do
        if x >= 0 and x < 56 and y >= 0 and y < 56 then
          image:setPixel(x, y, shade, shade, shade, 1)
        end
      end
    end
  end

  local function generatedPath(name)
    return "battle/" .. name .. ".png"
  end

  local function makeBlockGlitch(seed, x0, width)
    local image = ctx.blank(56, 56, 1, 1, 1, 0)
    local state = seed
    local function nextValue(limit)
      state = (state * 73 + 41) % 997
      return state % limit
    end

    -- Work in chunky 2x2 and 4x2 cells. This evokes the dense, tile-like
    -- output of an invalid Gen-I sprite stream without encoding captured art.
    for y = 4, 50, 2 do
      for x = x0, x0 + width - 2, 2 do
        local roll = nextValue(11)
        if roll < 6 then
          local shade = ({ 0, 0, 0.33, 0.67 })[nextValue(4) + 1]
          local cellWidth = nextValue(5) == 0 and 4 or 2
          setRect(image, x, y, cellWidth, 2, shade)
        end
      end
    end

    -- Strong horizontal records keep the result blocky and prevent the
    -- readable-letter appearance of the previous font-glyph prototype.
    for y = 8, 46, 8 do
      local inset = nextValue(5)
      setRect(image, x0 + inset, y, math.max(4, width - inset), 2,
        nextValue(3) == 0 and 0.33 or 0)
    end
    return image
  end

  local function makeClassicMissingNoFront()
    -- Exact ordinary Red/Blue MissingNo. front, assembled only from graphics
    -- already present in the player's public-Recomp cache. The recipe stores
    -- crop coordinates and placement; it contains no captured pixels, ROM
    -- bytes, encoded picture payload, or dependency on an engine change.
    local sourcePaths = {
      "battle/trainers/bruno.png",
      "battle/trainers/bugcatcher.png",
      "battle/back/abrab.png",
    }
    local sources = {}
    for index, path in ipairs(sourcePaths) do
      -- A partial/headless validation cache may not contain battle art. In a
      -- real imported Gen1 cache all three are standard assets. Leave the
      -- output absent if the cache itself is incomplete; never substitute a
      -- different picture.
      if not ctx.exists(path) then return nil end
      sources[index] = ctx.readImage(path)
    end
    local pieces = {
      { 1, 25, 0 }, { 1, 36, 35 }, { 1, 32, 2 }, { 1, 5, 39 },
      { 1, 24, 10 }, { 1, 22, 38 }, { 1, 15, 12 }, { 1, 30, 30 },
      { 1, 19, 13 }, { 1, 19, 31 }, { 1, 31, 3 }, { 2, 36, 31 },
      { 3, 18, 13 }, { 1, 12, 18 }, { 1, 23, 11 }, { 1, 12, 44 },
      { 1, 25, 42 }, { 1, 13, 35 }, { 2, 24, 23 }, { 1, 26, 0 },
      { 1, 34, 13 }, { 1, 36, 10 }, { 1, 16, 11 }, { 1, 23, 10 },
      { 1, 26, 1 }, { 1, 33, 12 }, { 1, 25, 1 }, { 1, 20, 32 },
      { 1, 21, 3 }, { 1, 35, 32 }, { 1, 25, 32 }, { 1, 33, 19 },
      { 1, 27, 3 }, { 1, 34, 35 }, { 1, 11, 51 }, { 1, 4, 32 },
      { 2, 21, 12 }, { 2, 24, 52 }, { 1, 23, 18 }, { 1, 33, 4 },
      { 1, 23, 19 }, { 1, 40, 14 }, { 1, 37, 8 }, { 1, 46, 27 },
      { 1, 29, 4 }, { 1, 33, 5 }, { 1, 8, 53 }, { 1, 25, 5 },
      { 1, 31, 39 }, { 1, 35, 30 }, { 1, 15, 22 }, { 1, 31, 5 },
      { 2, 25, 24 }, { 1, 28, 12 }, { 1, 46, 39 }, { 1, 20, 1 },
      { 1, 31, 12 }, { 1, 22, 0 }, { 1, 32, 1 }, { 1, 13, 15 },
      { 1, 29, 52 }, { 1, 18, 35 }, { 1, 35, 9 }, { 2, 23, 13 },
      { 2, 11, 21 }, { 1, 11, 17 }, { 1, 31, 13 }, { 1, 34, 6 },
      { 1, 18, 48 }, { 1, 30, 17 }, { 1, 46, 32 }, { 1, 23, 2 },
      { 1, 12, 6 }, { 2, 22, 40 }, { 1, 21, 31 }, { 1, 33, 0 },
      { 1, 39, 15 }, { 1, 29, 34 }, { 1, 30, 7 }, { 1, 32, 0 },
    }
    local layout = {
      { 0, 0, 0, 0, 22, 0, 29, 62, 67, 42, 62, 42 },
      { 0, 0, 0, 0, 0, 0, 42, 30, 80, 80, 80, 29 },
      { 0, 0, 0, 0, 65, 35, 43, 75, 62, 62, 62, 75 },
      { 0, 0, 0, 0, 11, 15, 15, 15, 39, 61, 29, 39 },
      { 0, 0, 0, 0, 53, 77, 77, 77, 43, 34, 31, 77 },
      { 0, 0, 0, 0, 27, 76, 76, 76, 80, 80, 67, 62 },
      { 0, 0, 0, 0, 43, 62, 62, 61, 44, 6, 2, 44 },
      { 0, 0, 0, 0, 70, 5, 5, 50, 63, 23, 2, 16 },
      { 0, 0, 0, 0, 54, 41, 37, 33, 26, 77, 28, 74 },
      { 0, 0, 0, 0, 18, 80, 43, 61, 76, 61, 30, 43 },
      { 0, 0, 0, 0, 46, 44, 17, 44, 0, 0, 62, 34 },
      { 0, 0, 0, 0, 47, 35, 62, 29, 6, 6, 49, 6 },
      { 35, 35, 35, 29, 66, 31, 59, 59, 34, 62, 62, 75 },
      { 22, 0, 0, 30, 9, 45, 9, 13, 39, 67, 67, 67 },
      { 78, 75, 75, 25, 75, 34, 76, 0, 62, 42, 42, 42 },
      { 21, 72, 72, 63, 58, 16, 51, 6, 43, 34, 34, 76 },
      { 19, 74, 60, 77, 56, 4, 7, 2, 68, 34, 34, 57 },
      { 73, 80, 80, 30, 1, 48, 16, 49, 67, 42, 0, 43 },
      { 32, 29, 29, 62, 33, 29, 39, 67, 35, 35, 42, 24 },
      { 71, 12, 12, 12, 1, 4, 52, 16, 50, 50, 50, 20 },
      { 55, 42, 42, 42, 47, 69, 46, 48, 64, 64, 64, 14 },
      { 0, 0, 0, 0, 22, 68, 80, 62, 34, 34, 34, 36 },
      { 75, 75, 75, 75, 75, 67, 35, 35, 61, 61, 79, 76 },
      { 0, 0, 0, 0, 29, 68, 38, 38, 50, 3, 8, 67 },
      { 75, 75, 34, 34, 0, 29, 80, 80, 28, 33, 33, 40 },
      { 35, 35, 43, 39, 29, 62, 75, 62, 35, 61, 30, 30 },
      { 29, 29, 34, 62, 35, 35, 76, 76, 48, 7, 17, 10 },
      { 35, 35, 38, 68, 75, 75, 67, 39, 34, 68, 68, 42 },
    }
    local image = ctx.blank(56, 56, 1, 1, 1, 1)
    for row, cells in ipairs(layout) do
      for column, pieceId in ipairs(cells) do
        if pieceId ~= 0 then
          local piece = pieces[pieceId]
          ctx.blit(image, sources[piece[1]], 30 + column * 2,
            (row - 1) * 2, piece[2], piece[3], 2, 2)
        end
      end
    end
    -- Gen1 battle fronts treat color zero as transparent everywhere, not
    -- merely at the exterior edge. Normalize copied cache alpha accordingly.
    for y = 0, 55 do
      for x = 0, 55 do
        local r, g, b = image:getPixel(x, y)
        image:setPixel(x, y, r, g, b, r > 0.83 and 0 or 1)
      end
