  local missingnoFront = makeClassicMissingNoFront()
  if missingnoFront then
    ctx.writeImage(missingnoFront, generatedPath("front/g1gpp_missingno"))
  end

  local function makeClassicMissingNoBack()
    -- Gen1 back pictures are 28x28 source images; the battle renderer doubles
    -- them to 56x56. Assemble the accepted MissingNo. result from ordinary
    -- back pictures already in the player's imported cache. The recipe stores
    -- only crop coordinates and placement, never captured pixels.
    local sourcePaths = {
      "battle/back/gravelerb.png",
      "battle/back/cloysterb.png",
      "battle/back/beedrillb.png",
    }
    local sources = {}
    for index, path in ipairs(sourcePaths) do
      if not ctx.exists(path) then return nil end
      sources[index] = ctx.readImage(path)
    end
    local pieces = {
      { 1, 19, 11 }, { 1, 24, 5 }, { 2, 10, 2 }, { 1, 5, 5 },
      { 1, 6, 4 }, { 1, 9, 20 }, { 1, 23, 13 }, { 1, 23, 15 },
      { 1, 4, 17 }, { 1, 8, 19 }, { 1, 9, 24 }, { 1, 4, 27 },
      { 1, 7, 9 }, { 1, 23, 20 }, { 1, 23, 12 }, { 1, 8, 20 },
      { 3, 9, 22 }, { 1, 10, 27 }, { 1, 16, 20 }, { 2, 24, 18 },
      { 1, 3, 3 }, { 1, 13, 11 }, { 1, 0, 17 }, { 1, 19, 7 },
      { 1, 5, 2 }, { 2, 23, 20 }, { 1, 7, 6 }, { 2, 15, 3 },
      { 1, 3, 2 }, { 1, 0, 0 },
    }
    local layout = {
      { 8,29,29,29,16,7,7,7,4,30,30,30,7,7 },
      { 25,7,7,7,16,30,30,30,4,30,30,30,8,8 },
      { 3,8,8,8,16,29,29,29,4,30,30,27,21,21 },
      { 16,22,22,22,15,7,7,7,5,30,30,30,30,30 },
      { 17,27,27,27,10,7,7,7,30,30,30,26,7,7 },
      { 16,12,12,12,14,12,12,12,11,11,11,24,7,7 },
      { 20,21,21,21,14,12,12,12,6,9,9,23,7,7 },
      { 20,21,21,21,20,13,13,13,30,30,30,26,12,12 },
      { 4,7,7,7,4,30,30,30,30,30,30,8,7,7 },
      { 4,13,13,13,4,30,30,30,25,30,30,21,8,8 },
      { 20,13,13,13,18,26,26,26,1,1,1,19,30,30 },
      { 2,24,24,24,28,7,7,7,2,24,24,9,26,26 },
      { 30,30,30,30,4,30,30,30,30,30,30,30,29,29 },
      { 30,30,30,30,4,30,30,30,26,26,26,26,7,7 },
    }
    local image = ctx.blank(28, 28, 1, 1, 1, 1)
    for row, cells in ipairs(layout) do
      for column, pieceId in ipairs(cells) do
        local piece = pieces[pieceId]
        ctx.blit(image, sources[piece[1]], (column - 1) * 2,
          (row - 1) * 2, piece[2], piece[3], 2, 2)
      end
    end
    for y = 0, 27 do
      for x = 0, 27 do
        local r, g, b = image:getPixel(x, y)
        image:setPixel(x, y, r, g, b, r > 0.83 and 0 or 1)
      end
    end
    return image
  end

  local missingnoBack = makeClassicMissingNoBack()
  if missingnoBack then
    ctx.writeImage(missingnoBack, generatedPath("back/g1gpp_missingno"))
  end

  -- The fossil and Ghost forms have separately documented state-dependent
  -- player-side data. Keep their bounded placeholder separate so the exact
  -- ordinary-MissingNo. back is not incorrectly assigned to those forms.
  local contextualBack = ctx.blank(28, 28, 1, 1, 1, 0)
  local contextualState = 18184
  for y = 2, 25, 2 do
    for x = 0, 9, 2 do
      contextualState = (contextualState * 73 + 41) % 997
      if contextualState % 11 < 6 then
        local shade = ({ 0, 0, 0.33, 0.67 })[(contextualState % 4) + 1]
        for dy = 0, 1 do
          for dx = 0, 1 do
            contextualBack:setPixel(x + dx, y + dy,
              shade, shade, shade, 1)
          end
        end
      end
    end
  end
  ctx.writeImage(contextualBack,
    generatedPath("back/g1gpp_missingno_contextual"))

  local function makeClassicMissingNoIcon()
    -- All Red/Blue MissingNo. slots map to Pokédex number zero. The original
    -- out-of-range icon class reuses these two ordinary cache sprites.
    local cooltrainer = ctx.exists("sprites/cooltrainer_m.png")
        and ctx.readImage("sprites/cooltrainer_m.png") or nil
    local gamblerAsleep = ctx.exists("sprites/gambler_asleep.png")
        and ctx.readImage("sprites/gambler_asleep.png") or nil
    if not cooltrainer or not gamblerAsleep then return nil end
    local icon = ctx.blank(16, 32, 1, 1, 1, 1)
    local function shade(image, x, y)
      local r, g, b = image:getPixel(x, y)
      local luminance = ((r or 1) + (g or 1) + (b or 1)) / 3
      if luminance < 0.17 then return 0 end
      if luminance < 0.50 then return 0.33 end
      return 1
    end
    local function mirroredTile(image, sourceY, targetY)
      for y = 0, 7 do
        for x = 0, 7 do
          local value = shade(image, x, sourceY + y)
          icon:setPixel(x, targetY + y, value, value, value, 1)
          icon:setPixel(15 - x, targetY + y, value, value, value, 1)
        end
      end
    end
    mirroredTile(cooltrainer, 0, 0)
    mirroredTile(cooltrainer, 8, 8)
    mirroredTile(gamblerAsleep, 0, 16)
    mirroredTile(gamblerAsleep, 8, 24)
    return icon
  end

  local missingnoIcon = makeClassicMissingNoIcon()
  if missingnoIcon then
    ctx.writeImage(missingnoIcon, "icons/g1gpp_missingno.png")
  end

  -- These special battle pictures already belong to the player's imported
  -- cache. Copy them into this mod's derived tree so gameplay code never
  -- points back into the ROM cache directly.
  for _, name in ipairs({ "fossilkabutops", "fossilaerodactyl", "ghost" }) do
    local rel = "battle/front/" .. name .. ".png"
    if ctx.exists(rel) then
      ctx.writeImage(ctx.readImage(rel), rel)
    end
  end

  for _, index in ipairs({ 200, 208, 230 }) do
    local image = makeBlockGlitch(index * 17, 5 + (index % 4),
      20 + (index % 3) * 2)
    ctx.writeImage(image,
      generatedPath("front/g1gpp_species_" .. tostring(index)))
  end

  local function makeCorruptedCopy(sourcePath, reverse, seed)
    if not ctx.exists(sourcePath) then
      return makeBlockGlitch(seed, 4, 36)
    end
    local source = ctx.readImage(sourcePath)
    local sw, sh = source:getDimensions()
    local out = ctx.blank(sw, sh, 1, 1, 1, 0)
    for y = 0, sh - 1 do
      local band = math.floor(y / 4)
      local shift = ((band * 11 + seed) % 13) - 6
      for x = 0, sw - 1 do
        local sourceX = reverse and (sw - 1 - x) or x
        sourceX = (sourceX + shift) % sw
        local r, g, b, a = source:getPixel(sourceX, y)
        if ((x + band * 3 + seed) % 17) < 14 then
          out:setPixel(x, y, r, g, b, a)
        end
      end
    end
    return out
  end

  local corruptedEnemy = makeCorruptedCopy(
    "battle/trainers/channeler.png", false, 47)
  ctx.writeImage(corruptedEnemy,
    generatedPath("trainers/g1gpp_corrupted_enemy_trainer"))

  -- JACRED's player-side graphic must face left. Flip the player-owned Red
  -- back picture first, then offset four-pixel bands to corrupt it.
  local corruptedBack = makeCorruptedCopy("battle/redb.png", true, 83)
  ctx.writeImage(corruptedBack,
    generatedPath("g1gpp_corrupted_trainer_back"))

  local frontSource192 = "battle/glitch/front/192.png"
  local front
  if ctx.exists(frontSource192) then
    -- Generated by Gen1Recomp from the player's own Red/Blue ROM. The mod
    -- ships no captured pixels; it only copies the importer result into its
    -- private derived-assets tree.
    front = ctx.readImage(frontSource192)
  else
    -- Compatibility fallback for public Recomp builds predating the ROM
    -- importer extension. This is deterministic geometry, never ROM data.
    front = ctx.blank(56, 56, 1, 1, 1, 0)
    local block192 = makeBlockGlitch(192, 7, 20)
    ctx.blit(front, block192, 0, 0)
  end
  ctx.writeImage(front, "battle/front/g1gpp_species_192_a.png")

  local back = makeBlockGlitch(292, 0, 18)
  ctx.writeImage(back, "battle/back/g1gpp_species_192_a.png")

  -- Index $C5 / 197. These are release-safe geometric reconstructions keyed
  -- to accepted capture metadata; no captured sprite pixels are copied.
  local front197 = ctx.blank(56, 56, 1, 1, 1, 0)
  local state197 = 197
  for y = 39, 55, 2 do
    for x = 7, 55, 2 do
      state197 = (state197 * 73 + 41) % 997
      if state197 % 7 < 4 then
        local shade = ({ 0, 0.33, 0.67 })[(state197 % 3) + 1]
        setRect(front197, x, y, state197 % 5 == 0 and 4 or 2, 2, shade)
      end
    end
  end
  ctx.writeImage(front197, "battle/front/g1gpp_species_197_c5.png")

  local back197 = ctx.blank(56, 56, 1, 1, 1, 0)
  for y = 0, 55, 4 do
    local inset = (y * 5 + 197) % 11
    local shade = (math.floor(y / 4) % 3 == 0) and 0 or 0.67
    setRect(back197, inset, y, 56 - inset, 2, shade)
    if y % 8 == 0 then
      setRect(back197, (inset + 17) % 32, y + 2, 22, 2, 0.33)
    end
  end
  ctx.writeImage(back197, "battle/back/g1gpp_species_197_c5.png")

  -- Class $0C falls outside the normal party-icon table. Accepted OAM
  -- evidence shows frame one reusing Fisher cache tiles $30/$32 and frame two
  -- reusing Swimmer cache tiles $70/$72, with the right half mirrored. Build
  -- that exact result from the player's extracted cache; no research pixels
  -- are packaged.
  local icon197 = ctx.blank(16, 32, 1, 1, 1, 1)
  local fisher197 = ctx.exists("sprites/fisher.png")
      and ctx.readImage("sprites/fisher.png") or nil
  local swimmer197 = ctx.exists("sprites/swimmer.png")
      and ctx.readImage("sprites/swimmer.png") or nil
  local function partyShade(image, x, y)
    local r, g, b = image:getPixel(x, y)
    local luminance = ((r or 1) + (g or 1) + (b or 1)) / 3
    if luminance < 0.17 then return 0 end
    if luminance < 0.50 then return 0.33 end
    return 1
  end
  local function mirroredTile(image, sourceY, targetY)
    for y = 0, 7 do
      for x = 0, 7 do
        local shade = partyShade(image, x, sourceY + y)
        icon197:setPixel(x, targetY + y, shade, shade, shade, 1)
        icon197:setPixel(15 - x, targetY + y, shade, shade, shade, 1)
      end
    end
  end
  if fisher197 and swimmer197 then
    mirroredTile(fisher197, 0, 0)
    mirroredTile(fisher197, 8, 8)
    mirroredTile(swimmer197, 0, 16)
    mirroredTile(swimmer197, 24, 24)
  else
    local fallback = makeBlockGlitch(19712, 0, 8)
    ctx.blit(icon197, fallback, 0, 0)
    ctx.blit(icon197, fallback, 0, 16)
  end
  ctx.writeImage(icon197, "icons/g1gpp_species_197_c5.png")

  -- The leading $21/$14 name bytes are live VRAM corruption, not Japanese
  -- characters. Represent their captured position with inert generated block
  -- glyphs, without copying or executing ROM-derived tile data.
  local name197 = ctx.blank(16, 8, 1, 1, 1, 0)
  local patterns197 = {
    { 0xF3, 0x9F, 0x7B, 0xEF, 0xAD, 0xF7, 0x5E, 0xC3 },
    { 0x6F, 0xF9, 0xBD, 0xE7, 0x7E, 0xDB, 0xF5, 0x9C },
  }
  for glyph = 0, 1 do
    for y = 0, 7 do
      local row = patterns197[glyph + 1][y + 1]
      for x = 0, 7 do
        if math.floor(row / (2 ^ (7 - x))) % 2 == 1 then
          name197:setPixel(glyph * 8 + x, y, 0, 0, 0, 1)
        end
      end
    end
  end
  ctx.writeImage(name197, "fonts/g1gpp_species_197_name.png")

  -- Snake.exe artwork is derived locally from the player's own imported
  -- Gen1Recomp cache.  Keep only the tiny cells the minigame needs so the
  -- distributable remains source-only and contains no extracted game art.
  if ctx.exists("battle/balls.png") then
    local source = ctx.readImage("battle/balls.png")
    local ball = ctx.blank(8, 8, 1, 1, 1, 0)
    ctx.blit(ball, source, 0, 0, 0, 0, 8, 8)
    ctx.writeImage(ball, "ui/g1gpp_snake_ball.png")
  end

  -- Red/Blue has no ordinary printable percent character in its English
  -- charmap. Supply one as source-generated geometry in a private font page;
  -- no font image or other external artwork is distributed with the mod.
  local percent = ctx.blank(8, 8, 1, 1, 1, 0)
  local percentPattern = {
    " ##   # ",
    "#  # #  ",
    " ## #   ",
    "   #    ",
    "  # ##  ",
    " # #  # ",
    "#   ##  ",
    "        ",
  }
  for y, row in ipairs(percentPattern) do
    for x = 1, 8 do
      if row:sub(x, x) == "#" then
        percent:setPixel(x - 1, y - 1, 0, 0, 0, 1)
      end
    end
  end
  ctx.writeImage(percent, "ui/g1gpp_snake_percent.png")

  if ctx.exists("slots/symbols.png") then
    local source = ctx.readImage("slots/symbols.png")
    local candy = ctx.blank(8, 8, 1, 1, 1, 0)
    -- Recompose the CHERRY cell's own four imported shades into a compact
    -- wrapped-candy silhouette. The reference establishes the object shape;
    -- every rendered color still comes from the player's cartridge cache.
    local shadeSamples = {}
    local shadeDistance = { math.huge, math.huge, math.huge, math.huge }
    local targets = { 0, 1 / 3, 2 / 3, 1 }
    for y = 0, 15 do
      for x = 0, 15 do
        local r, g, b, a = source:getPixel(32 + x, y)
        if (a or 0) >= 0.5 then
          local luminance = ((r or 1) + (g or 1) + (b or 1)) / 3
          for shade, target in ipairs(targets) do
            local distance = math.abs(luminance - target)
            if distance < shadeDistance[shade] then
              shadeDistance[shade] = distance
              shadeSamples[shade] = { r, g, b, a }
            end
          end
        end
      end
    end
    local pattern = {
      "##    ##",
      "#.#  #.#",
      " .####. ",
      "##+..+##",
      "##+..+##",
      " .####. ",
      "#.#  #.#",
      "##    ##",
    }
    local shadeFor = { ["#"] = 1, ["+"] = 2, ["."] = 3 }
    for y, row in ipairs(pattern) do
      for x = 1, 8 do
        local shade = shadeFor[row:sub(x, x)]
        local color = shade and shadeSamples[shade]
        if color then
          candy:setPixel(x - 1, y - 1,
            color[1], color[2], color[3], color[4])
        end
      end
    end
    ctx.writeImage(candy, "ui/g1gpp_snake_candy.png")
  end

  if ctx.exists("sprites/red.png") then
    local source = ctx.readImage("sprites/red.png")
    local micro = ctx.blank(8, 48, 1, 1, 1, 0)
    local shadeValues = { 0, 1 / 3, 2 / 3, 1 }

    local function shadeIndex(r, g, b)
      local luminance = ((r or 1) + (g or 1) + (b or 1)) / 3
      if luminance < 0.17 then return 1 end
      if luminance < 0.50 then return 2 end
      if luminance < 0.84 then return 3 end
      return 4
    end

    -- A normal 50% nearest-neighbour draw keeps only one arbitrary pixel
    -- from each 2x2 source block, which made Red look like broken fragments.
    -- Reduce every directional frame with an outline-aware vote instead:
    -- isolated black outline pixels survive, two-or-more visible pixels keep
    -- the body, and ties favor the darker shade that defines cap/face/body.
    for frame = 0, 5 do
      for y = 0, 7 do
        for x = 0, 7 do
          local counts = { 0, 0, 0, 0 }
          local visible = 0
          for sy = 0, 1 do
            for sx = 0, 1 do
              local r, g, b, a = source:getPixel(
                x * 2 + sx, frame * 16 + y * 2 + sy)
              if (a or 0) >= 0.5 then
                local shade = shadeIndex(r, g, b)
                counts[shade] = counts[shade] + 1
                visible = visible + 1
              end
            end
          end

          local chosen
          if visible == 1 then
            chosen = counts[1] == 1 and 1 or nil
          elseif visible >= 2 then
            local best = -1
            for shade = 1, 4 do
              local outlineBias = shade == 1 and 0.35
                or shade == 2 and 0.15 or 0
              local score = counts[shade] + outlineBias
              if counts[shade] > 0 and score > best then
                best = score
                chosen = shade
              end
            end
          end
          if chosen then
            local value = shadeValues[chosen]
            micro:setPixel(x, frame * 8 + y, value, value, value, 1)
          end
        end
      end
    end
    ctx.writeImage(micro, "ui/g1gpp_snake_player.png")
  end





  -- Full retained-roster visual reconstruction. Accepted mGBA images are
  -- private comparison oracles only. This table contains source-cache crop
  -- coordinates and placements; every output pixel is read from ordinary
  -- graphics generated by the player's own public Gen1Recomp import.
  local rosterSourceCache = {}
  local function rosterSource(index)
    local image = rosterSourceCache[index]
    if image then return image end
    local path = G1GPP_ROSTER_RECIPES.sources[index]
    if not (path and ctx.exists(path)) then
      error("required player-cache source missing: " .. tostring(path))
    end
    image = ctx.readImage(path)
    rosterSourceCache[index] = image
    return image
  end
  local function rosterShade(r, g, b, a, transparent)
    local lum = ((r or 1) + (g or 1) + (b or 1)) / 3
    local value
    if transparent and ((a or 1) < 0.5 or lum > 0.933) then value = 1
    elseif lum < 0.168 then value = 0
    elseif lum < 0.502 then value = 1 / 3
    elseif lum < 0.835 then value = 2 / 3
    else value = 1 end
    local alpha = transparent and value > 0.99 and 0 or 1
    return value, value, value, alpha
  end
  local function buildRosterImage(spec)
    local out = ctx.blank(spec.w, spec.h, 1, 1, 1, spec.t and 0 or 1)
    for _, piece in ipairs(spec.p) do
      local source = rosterSource(piece[1])
      for y = 0, piece[6] - 1 do
        for x = 0, piece[6] - 1 do
          local r, g, b, a = source:getPixel(piece[2] + x, piece[3] + y)
          out:setPixel(piece[4] + x, piece[5] + y,
            rosterShade(r, g, b, a, spec.t))
        end
      end
    end
    return out
  end
  for index, entry in pairs(G1GPP_ROSTER_RECIPES.entries) do
    local suffix = ("%03d"):format(index)
    ctx.writeImage(buildRosterImage(entry.front),
      "battle/front/g1gpp_species_" .. suffix .. ".png")
    ctx.writeImage(buildRosterImage(entry.back),
      "battle/back/g1gpp_species_" .. suffix .. ".png")
    ctx.writeImage(buildRosterImage(entry.icon),
      "icons/g1gpp_species_" .. suffix .. ".png")
    ctx.writeImage(buildRosterImage(entry.name),
      "fonts/g1gpp_name_" .. suffix .. ".png")
    if entry.dex then
      ctx.writeImage(buildRosterImage(entry.dex),
        "ui/g1gpp_dex_" .. suffix .. ".png")
    end
    if entry.dex2 then
      ctx.writeImage(buildRosterImage(entry.dex2),
        "ui/g1gpp_dex_" .. suffix .. "_2.png")
    end
    if entry.dex3 then
      ctx.writeImage(buildRosterImage(entry.dex3),
        "ui/g1gpp_dex_" .. suffix .. "_3.png")
    end
    if entry.dexfull then
      ctx.writeImage(buildRosterImage(entry.dexfull),
        "ui/g1gpp_dex_full_" .. suffix .. ".png")
    end
  end

end
